import java.util.Arrays;
import java.util.List;

public final class BTreeTest {
    public static void main(String[] args) {
        shouldRejectInvalidMinDegree();
        shouldReportEmptyState();
        shouldPreserveSortedTraversalAcrossInsertions();
        shouldSupportMembershipChecks();
    }

    private static void shouldRejectInvalidMinDegree() {
        boolean threw = false;
        try {
            new BTree(1);
        } catch (IllegalArgumentException exception) {
            threw = true;
        }

        assertTrue(threw, "Expected invalid minimum degree to be rejected.");
    }

    private static void shouldReportEmptyState() {
        BTree tree = new BTree(3);

        assertTrue(tree.isEmpty(), "Expected a new tree to be empty.");
        assertEquals("", tree.toString(), "Expected empty tree string representation to be blank.");
        assertEquals(List.of(), tree.toList(), "Expected empty tree traversal to have no keys.");
    }

    private static void shouldPreserveSortedTraversalAcrossInsertions() {
        BTree tree = new BTree(3);
        int[] insertedKeys = {10, 20, 5, 6, 12, 30, 7, 17};

        for (int key : insertedKeys) {
            tree.insert(key);
        }

        List<Integer> expectedKeys = Arrays.asList(5, 6, 7, 10, 12, 17, 20, 30);
        assertEquals(expectedKeys, tree.toList(), "Expected in-order traversal to stay sorted.");
        assertEquals("5 6 7 10 12 17 20 30", tree.toString(), "Expected stable string rendering.");
    }

    private static void shouldSupportMembershipChecks() {
        BTree tree = new BTree(2);
        int[] insertedKeys = {8, 9, 10, 11, 15, 20, 17};

        for (int key : insertedKeys) {
            tree.insert(key);
        }

        assertTrue(tree.contains(10), "Expected inserted key to be found.");
        assertTrue(tree.contains(17), "Expected inserted key to be found.");
        assertFalse(tree.contains(4), "Expected missing key to be absent.");
        assertFalse(tree.isEmpty(), "Expected populated tree to report non-empty.");
    }

    private static void assertEquals(Object expected, Object actual, String message) {
        if (!expected.equals(actual)) {
            throw new AssertionError(message + " Expected: " + expected + ", Actual: " + actual);
        }
    }

    private static void assertTrue(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }

    private static void assertFalse(boolean condition, String message) {
        assertTrue(!condition, message);
    }
}

public final class Main {
    private static final int MIN_DEGREE = 3;
    private static final int[] SAMPLE_KEYS = {10, 20, 5, 6, 12, 30, 7, 17};

    public static void main(String[] args) {
        BTree tree = buildSampleTree();

        System.out.println("Traversal of the constructed tree is " + tree);

        printSearchResult(tree, 6);
        printSearchResult(tree, 15);
    }

    private static BTree buildSampleTree() {
        BTree tree = new BTree(MIN_DEGREE);
        for (int key : SAMPLE_KEYS) {
            tree.insert(key);
        }
        return tree;
    }

    private static void printSearchResult(BTree tree, int key) {
        if (tree.contains(key)) {
            System.out.println(" | Present");
        } else {
            System.out.println(" | Not Present");
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.StringJoiner;
import java.util.function.IntConsumer;

public final class BTree {
    private final int minDegree;
    private Node root;

    public BTree(int minDegree) {
        validateMinDegree(minDegree);
        this.minDegree = minDegree;
    }

    public void insert(int key) {
        if (root == null) {
            root = Node.leaf(minDegree, key);
            return;
        }

        splitRootIfNeeded();
        root.insertNonFull(key);
    }

    public boolean contains(int key) {
        return root != null && root.contains(key);
    }

    public boolean isEmpty() {
        return root == null;
    }

    public void forEachKey(IntConsumer action) {
        Objects.requireNonNull(action, "action");
        if (root != null) {
            root.forEachKey(action);
        }
    }

    public List<Integer> toList() {
        List<Integer> orderedKeys = new ArrayList<>();
        forEachKey(orderedKeys::add);
        return orderedKeys;
    }

    public String traversal() {
        return toString();
    }

    public void traverse() {
        System.out.print(this);
    }

    private void splitRootIfNeeded() {
        if (!root.isFull()) {
            return;
        }

        Node newRoot = Node.internal(minDegree);
        newRoot.setChild(0, root);
        newRoot.splitChild(0);
        root = newRoot;
    }

    private static void validateMinDegree(int minDegree) {
        if (minDegree < 2) {
            throw new IllegalArgumentException("B-tree minimum degree must be at least 2.");
        }
    }

    @Override
    public String toString() {
        StringJoiner joiner = new StringJoiner(" ");
        forEachKey(key -> joiner.add(Integer.toString(key)));
        return joiner.toString();
    }

    private static final class Node {
        private final int minDegree;
        private final int[] keys;
        private final Node[] children;
        private final boolean leaf;
        private int keyCount;

        private Node(int minDegree, boolean leaf) {
            this.minDegree = minDegree;
            this.leaf = leaf;
            this.keys = new int[maxKeysFor(minDegree)];
            this.children = new Node[maxChildrenFor(minDegree)];
        }

        private static Node leaf(int minDegree, int firstKey) {
            Node node = new Node(minDegree, true);
            node.keys[0] = firstKey;
            node.keyCount = 1;
            return node;
        }

        private static Node internal(int minDegree) {
            return new Node(minDegree, false);
        }

        private static int maxKeysFor(int minDegree) {
            return 2 * minDegree - 1;
        }

        private static int maxChildrenFor(int minDegree) {
            return 2 * minDegree;
        }

        private boolean isFull() {
            return keyCount == keys.length;
        }

        private void setChild(int index, Node child) {
            children[index] = child;
        }

        private boolean contains(int targetKey) {
            int index = findKeyIndex(targetKey);
            if (matchesKeyAt(index, targetKey)) {
                return true;
            }

            return !leaf && children[index].contains(targetKey);
        }

        private void forEachKey(IntConsumer action) {
            for (int i = 0; i < keyCount; i++) {
                if (!leaf) {
                    children[i].forEachKey(action);
                }
                action.accept(keys[i]);
            }

            if (!leaf) {
                children[keyCount].forEachKey(action);
            }
        }

        private void insertNonFull(int key) {
            if (leaf) {
                insertIntoLeaf(key);
                return;
            }

            int childIndex = findKeyIndex(key);
            childIndex = prepareChildForInsert(childIndex, key);
            children[childIndex].insertNonFull(key);
        }

        private void insertIntoLeaf(int key) {
            int insertAt = keyCount - 1;
            while (insertAt >= 0 && keys[insertAt] > key) {
                keys[insertAt + 1] = keys[insertAt];
                insertAt--;
            }

            keys[insertAt + 1] = key;
            keyCount++;
        }

        private int prepareChildForInsert(int childIndex, int key) {
            if (!children[childIndex].isFull()) {
                return childIndex;
            }

            splitChild(childIndex);
            if (key > keys[childIndex]) {
                return childIndex + 1;
            }
            return childIndex;
        }

        private void splitChild(int childIndex) {
            Node child = children[childIndex];
            Node sibling = new Node(child.minDegree, child.leaf);
            int medianKey = child.keys[medianKeyIndex()];

            sibling.keyCount = minDegree - 1;
            copyUpperHalfOfKeys(child, sibling);
            if (!child.leaf) {
                copyUpperHalfOfChildren(child, sibling);
            }

            child.keyCount = minDegree - 1;
            shiftChildrenRight(childIndex + 1);
            children[childIndex + 1] = sibling;

            shiftKeysRight(childIndex);
            keys[childIndex] = medianKey;
            keyCount++;
        }

        private void copyUpperHalfOfKeys(Node source, Node destination) {
            for (int i = 0; i < minDegree - 1; i++) {
                destination.keys[i] = source.keys[i + minDegree];
            }
        }

        private void copyUpperHalfOfChildren(Node source, Node destination) {
            for (int i = 0; i < minDegree; i++) {
                destination.children[i] = source.children[i + minDegree];
            }
        }

        private void shiftChildrenRight(int fromIndex) {
            for (int i = keyCount; i >= fromIndex; i--) {
                children[i + 1] = children[i];
            }
        }

        private void shiftKeysRight(int fromIndex) {
            for (int i = keyCount - 1; i >= fromIndex; i--) {
                keys[i + 1] = keys[i];
            }
        }

        private int findKeyIndex(int targetKey) {
            int index = 0;
            while (index < keyCount && targetKey > keys[index]) {
                index++;
            }
            return index;
        }

        private boolean matchesKeyAt(int index, int targetKey) {
            return index < keyCount && keys[index] == targetKey;
        }

        private int medianKeyIndex() {
            return minDegree - 1;
        }
    }
}

